export const statusLabel=value=>labels[value]||value||'—';
export function icon(name,size=20){const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',mail:'M3 5h18v14H3z M3 6l9 7 9-7',crm:'M9 3h6v4H9z M7 5H5v16h14V5h-2 M8 12h8 M8 16h5',school:'M3 10l9-7 9 7 M5 9v12h14V9 M9 21v-7h6v7',people:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M16 3.13a4 4 0 0 1 0 7.75',book:'M3 3h6a3 3 0 0 1 3 3v15a4 4 0 0 0-4-2H3z M21 3h-6a3 3 0 0 0-3 3v15a4 4 0 0 1 4-2h5z',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1z',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 M13 6l6 6-6 6',search:'M21 21l-5-5 M10.5 3a7.5 7.5 0 1 0 0 15 7.5 7.5 0 0 0 0-15',upload:'M12 16V3 M7 8l5-5 5 5 M3 15v6h18v-6',check:'M5 12l4 4L19 6',clock:'M12 8v5l3 2 M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20',menu:'M3 6h18 M3 12h18 M3 18h18',logout:'M9 3H4v18h5 M14 7l5 5-5 5 M8 12h12',file:'M14 2H4v20h16V8z M14 2v6h6 M8 13h8 M8 17h5',refresh:'M20 7v5h-5 M4 17v-5h5 M6 7a7 7 0 0 1 12-1l2 3 M4 15l2 3a7 7 0 0 0 12-1',close:'M6 6l12 12 M18 6L6 18',pause:'M8 5v14 M16 5v14',send:'M22 2L9 15 M22 2l-7 20-6-7-7-6z'};return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.file}"/></svg>`;}
const fmt=value=>value?new Date(value).toLocaleString('fr-FR',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'}):'—';
const badge=value=>`<span class="status ${['ADMITTED','ACCEPTED','DELIVERED','APPROVED','COMPLETE','ACTIVE','SUBMITTED'].includes(value)?'ok':['UNSUBSCRIBED','DISQUALIFIED','FAILED','BOUNCED','COMPLAINED','REJECTED'].includes(value)?'no':['UNCERTAIN','MISSING_DOCUMENTS'].includes(value)?'warn':''}">${h(statusLabel(value))}</span>`;
const empty=(title,text,action='')=>`<div class="empty"><div class="empty-icon">${icon('file',30)}</div><h3>${h(title)}</h3><p>${h(text)}</p>${action}</div>`;
export function parseCSV(text){
 text=text.replace(/^\uFEFF/,'');
 const first=text.split(/\r?\n/)[0]||'',separator=(first.match(/;/g)||[]).length>(first.match(/,/g)||[]).length?';':',';
 let rows=[],row=[],cell='',quoted=false;
 for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++;}else if(!quoted&&cell!=='')throw Error('Guillemet inattendu dans le fichier CSV.');else quoted=!quoted;}
 else if(c===separator&&!quoted){row.push(cell);cell='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(v=>v.trim()))rows.push(row);row=[];cell='';}else cell+=c;}
 if(quoted)throw Error('Le fichier CSV contient un champ entre guillemets non fermé.');row.push(cell);if(row.some(v=>v.trim()))rows.push(row);
 if(rows.length<2)throw Error('Le fichier doit contenir un en-tête et au moins un prospect.');
 const header=rows.shift().map(v=>v.trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/\s+/g,'_'));
 if(new Set(header).size!==header.length)throw Error('Les noms de colonnes doivent être uniques.');
 for(const key of ['full_name','email'])if(!header.includes(key))throw Error('Colonne obligatoire absente : '+key);
 if(rows.length>500)throw Error('Importez au maximum 500 prospects par fichier.');
 return rows.map((values,i)=>{if(values.length!==header.length)throw Error('Nombre de colonnes incorrect à la ligne '+(i+2));const result=Object.fromEntries(header.map((key,j)=>[key,values[j].trim()]));result.consent_email=['true','1','oui','yes'].includes(String(result.consent_email||'').toLowerCase());return result;});
}
