 async function request(action,data={},binary=false){const {data:{session}}=await client.auth.getSession();if(!session)throw Error(errors.authentication_required);const response=await fetch(action.startsWith('scan_')?ENDPOINT.replace('mbn-workspace','mbn-antivirus'):action.startsWith('meta_')?ENDPOINT.replace('mbn-workspace','mbn-meta'):action.startsWith('letter_')?ENDPOINT.replace('mbn-workspace','mbn-letters'):ENDPOINT,{method:'POST',headers:{Authorization:'Bearer '+session.access_token,apikey:PUBLIC_KEY,'Content-Type':'application/json'},body:JSON.stringify({action,data})});if(!response.ok){let result;try{result=await response.json();}catch{}throw Error(errors[result?.error]||scanErrors[result?.error]||letterErrors[result?.error]||metaErrors[result?.error]||`Action impossible (${response.status}).`);}return binary?response.blob():response.json();}
